-- A shared case has exactly one assigned-work owner. Retained original cases keep their native inbox.
CREATE OR REPLACE FUNCTION app.contract_inbox_projection() RETURNS jsonb LANGUAGE sql STABLE SECURITY DEFINER SET search_path=pg_catalog,public,pg_temp AS $$
 WITH candidates AS MATERIALIZED(SELECT c.id,c.number,c.employment_id,c.data->'term'->>'endOn' AS end_on,app.contract_case_task_kind(c.id) AS kind FROM public.contract_case c WHERE c.tenant_id=app.current_tenant_id() AND NOT EXISTS(SELECT 1 FROM public.contract_shared_case shared WHERE shared.tenant_id=c.tenant_id AND shared.case_id=c.id) AND app.contract_runtime(c.company_id) AND app.contract_case_access(c.id) AND c.data->>'state' NOT IN('cancelled','handed_off')),
 actionable AS MATERIALIZED(SELECT * FROM candidates WHERE kind IS NOT NULL),sample AS(SELECT * FROM actionable ORDER BY end_on,number,id LIMIT 20)
 SELECT jsonb_build_object('count',(SELECT count(*) FROM actionable),'items',coalesce((SELECT jsonb_agg(jsonb_build_object('caseId',s.id,'number',s.number,'name',p.full_name,'endOn',s.end_on,'kind',s.kind,'href','/lifecycle/contracts/'||s.id::text) ORDER BY s.end_on,s.number,s.id) FROM sample s JOIN public.employment e ON e.id=s.employment_id AND e.tenant_id=app.current_tenant_id() JOIN public.person p ON p.id=e.person_id AND p.tenant_id=e.tenant_id),'[]'::jsonb)); $$;
